import "strings"

// PathSegments splits a slash-separated path into its components, dropping empty
// segments (so "//a//b//" → ["a","b"]).
func PathSegments(p string) []string {
	var out []string
	for _, seg := range strings.Split(p, "/") {
		if seg != "" {
			out = append(out, seg)
		}
	}
	return out
}

// JoinPath joins segments with single slashes, ignoring empty segments.
func JoinPath(segs ...string) string {
	var nonEmpty []string
	for _, s := range segs {
		if s != "" {
			nonEmpty = append(nonEmpty, s)
		}
	}
	return strings.Join(nonEmpty, "/")
}

// HasExt reports whether p ends with the extension ext (which should include
// the leading dot, e.g. ".go").
func HasExt(p, ext string) bool {
	return strings.HasSuffix(p, ext)
